\section{Introduction}

\subsection{The mixing question}
Let $\sigma$ be a real-valued function of a scalar \emph{mass} parameter $t$, interpreted as the
growth rate, yield, or exponent produced by a mechanism supplied with mass $t$. The most basic
structural question about such a mechanism is whether it rewards homogenisation: given two masses
$s$ and $t$, is
\[
\frac{\sigma(s)+\sigma(t)}{2}\;\le\;\sigma\!\left(\frac{s+t}{2}\right)?
\]
If so, pooling two batches into one of average mass is never worse than running them separately
and averaging outputs. This is midpoint concavity, equivalent to concavity for continuous
functions. This paper answers the mixing question, sharply and in both directions, for the inverse
of a cubic whose derivative is a perfect square.

\subsection{The critical cubic}
Define
\[
h(y)\;=\;y^{3}-y^{2}+\frac{y}{3},\qquad y\in\R .
\]
Differentiating,
\[
h'(y)=3y^{2}-2y+\tfrac13=3\left(y-\tfrac13\right)^{2}\ \ge\ 0,
\]
with equality only at $y=1/3$: the two critical points of a generic cubic have collided into one
degenerate critical point, and up to affine normalisation $h$ is the unique monic cubic with
$h(0)=0$ having this property. In particular $h$ is strictly increasing, hence a bijection of
$\R$. The degeneracy is equivalent to the identity
\begin{equation}\label{eq:shift}
h(y)\;=\;\frac{(3y-1)^{3}+1}{27},
\end{equation}
so $h$ is an increasing affine reparametrisation of the pure cube $u\mapsto u^{3}$; the cubic
resolvent collapses to a single real radical.

\subsection{The Lagrange exponent}

\begin{definition}[real cube root]
For $x\in\R$ set $\cbrt{x}=x^{1/3}$ if $x\ge 0$ and $\cbrt{x}=-(-x)^{1/3}$ if $x<0$. This is the
unique real solution of $u^{3}=x$; it is odd, strictly increasing, and satisfies
$\bigl(\cbrt{x}\bigr)^{3}=x$ for all real $x$.
\end{definition}

\begin{definition}[Lagrange exponent]
The \emph{Lagrange exponent} is
\[
\sigma(t)\;=\;\frac{1+\cbrt{27t-1}}{3},\qquad t\in\R .
\]
\end{definition}

\begin{proposition}[inversion]\label{prop:inv}
For all $y,t\in\R$ we have $h(\sigma(t))=t$ and $\sigma(h(y))=y$. Moreover $\sigma$ is strictly
increasing and injective, and $h(y)=t$ implies $y=\sigma(t)$.
\end{proposition}

\begin{proof}
Since $3\sigma(t)-1=\cbrt{27t-1}$, identity~\eqref{eq:shift} gives
$h(\sigma(t))=\bigl((27t-1)+1\bigr)/27=t$. The other composite follows from injectivity of the
strictly monotone $h$. Strict monotonicity of $\sigma$ is inherited from $t\mapsto 27t-1$ and the
cube root.
\end{proof}

Sample values: $\sigma(0)=0$, $\sigma(1/27)=1/3$, $\sigma(1/3)=1$, $\sigma(28/27)=4/3$.

\begin{definition}[critical mass]
The \emph{critical mass} is $t_{c}=h(1/3)=1/27$, the image of the degenerate critical point; the
\emph{physical range} is $[1/27,\infty)$.
\end{definition}

\begin{proposition}
$\sigma(t)\ge 1/3$ if and only if $t\ge 1/27$.
\end{proposition}

\begin{proof}
Immediate from strict monotonicity and $\sigma(1/27)=1/3$.
\end{proof}

\section{Concavity above the critical mass}

\begin{lemma}[concavity of the radical]\label{lem:rpow}
The map $x\mapsto x^{1/3}$ is strictly concave on $[0,\infty)$.
\end{lemma}

\begin{lemma}[affine transport]\label{lem:transport}
Let $g$ be concave on an interval $J$, let $L(t)=\alpha t+\beta$ be affine with $L(I)\subseteq J$,
and let $\lambda>0$, $\mu\in\R$. Then $\lambda(g\circ L)+\mu$ is concave on $I$; if $g$ is
strictly concave and $\alpha\neq 0$, it is strictly concave.
\end{lemma}

\begin{proof}
Affine maps commute with convex combinations, $L(ax+by)=aL(x)+bL(y)$ when $a+b=1$; substitute into
the concavity inequality and apply the positive scaling and shift. If $x\ne y$ and $\alpha\ne 0$
then $L(x)\ne L(y)$, giving strictness.
\end{proof}

\begin{theorem}[Main Theorem]\label{thm:concave}
The Lagrange exponent $\sigma$ is concave on $[1/27,\infty)$: for all $x,y\ge 1/27$ and all
$a,b\ge 0$ with $a+b=1$,
\[
a\,\sigma(x)+b\,\sigma(y)\;\le\;\sigma(ax+by).
\]
\end{theorem}

\begin{proof}
Put $u=27x-1\ge0$ and $v=27y-1\ge0$. Since $a+b=1$,
\[
27(ax+by)-1=a(27x-1)+b(27y-1)=au+bv\ \ge\ 0 .
\]
All three arguments are nonnegative, so the sign-aware cube root agrees with $x\mapsto x^{1/3}$ at
each, and Lemma~\ref{lem:rpow} gives $a\,u^{1/3}+b\,v^{1/3}\le(au+bv)^{1/3}$. Multiplying by
$\tfrac13>0$ and adding $\tfrac13=\tfrac{a+b}{3}$ yields
\[
a\sigma(x)+b\sigma(y)=\frac{a+b+a u^{1/3}+b v^{1/3}}{3}
 \le\frac{1+(au+bv)^{1/3}}{3}=\sigma(ax+by). \qedhere
\]
\end{proof}

\begin{theorem}[strict concavity]\label{thm:strictconcave}
For $x\ne y$ in $[1/27,\infty)$ and $a,b>0$ with $a+b=1$ one has
$a\sigma(x)+b\sigma(y)<\sigma(ax+by)$.
\end{theorem}

\begin{proof}
As in Theorem~\ref{thm:concave}, using strict concavity in Lemma~\ref{lem:rpow}; injectivity of
$t\mapsto 27t-1$ transports $x\ne y$ to $u\ne v$.
\end{proof}

\begin{corollary}[midpoint form: averaging never hurts]\label{cor:midpoint}
For $s,t\ge1/27$,
\[
\frac{\sigma(s)+\sigma(t)}{2}\;\le\;\sigma\!\left(\frac{s+t}{2}\right),
\]
with strict inequality when $s\ne t$.
\end{corollary}

\begin{corollary}[Jensen form]\label{cor:jensen}
Let $T$ be finite, $w_{i}\ge0$ with $\sum_{i\in T}w_{i}=1$, and $m_{i}\ge1/27$. Then
\[
\sum_{i\in T}w_{i}\,\sigma(m_{i})\;\le\;\sigma\!\left(\sum_{i\in T}w_{i}m_{i}\right).
\]
\end{corollary}

\begin{proof}
The finite Jensen inequality for a concave function on the convex set $[1/27,\infty)$, obtained by
induction on $|T|$ from Theorem~\ref{thm:concave} after renormalising weights.
\end{proof}

\section{The mirror regime and sharpness of $1/27$}

\begin{theorem}[strict convexity below the critical mass]\label{thm:convex}
$\sigma$ is strictly convex on $(-\infty,1/27]$: for $x\ne y$ there and $a,b>0$ with $a+b=1$,
\[
\sigma(ax+by)\;<\;a\,\sigma(x)+b\,\sigma(y).
\]
\end{theorem}

\begin{proof}
Put $u=1-27x\ge0$, $v=1-27y\ge0$, $u\ne v$. Then $27(ax+by)-1=-(au+bv)$ with $au+bv\ge0$, and by
oddness of the cube root
\[
\cbrt{27x-1}=-u^{1/3},\quad \cbrt{27y-1}=-v^{1/3},\quad \cbrt{27(ax+by)-1}=-(au+bv)^{1/3}.
\]
Strict concavity of $x\mapsto x^{1/3}$ gives $a u^{1/3}+b v^{1/3}<(au+bv)^{1/3}$; negating flips
the inequality, and dividing by $3$ after adding $1=a+b$ gives the claim.
\end{proof}

\begin{remark}
Theorems~\ref{thm:strictconcave} and \ref{thm:convex} are the same proof run through two affine
substitutions: $t\mapsto27t-1$ (increasing, preserves the inequality) and $t\mapsto1-27t$
(decreasing, whose composition with negation reverses it). Hence the two regimes are exact mirror
images and the changeover is a single point.
\end{remark}

\begin{theorem}[sharpness on the right]\label{thm:sharpright}
For every $a<1/27$, $\sigma$ is not concave on $[a,\infty)$.
\end{theorem}

\begin{proof}
If it were, midpoint concavity applied to the pair $a,1/27\in[a,\infty)$ would give
$\tfrac12\sigma(a)+\tfrac12\sigma(1/27)\le\sigma\bigl(\tfrac{a+1/27}{2}\bigr)$. But the same pair
lies in $(-\infty,1/27]$ and is distinct, so Theorem~\ref{thm:convex} with weights
$\tfrac12,\tfrac12$ gives the strict reverse inequality --- a contradiction.
\end{proof}

\begin{theorem}[sharpness on the left]\label{thm:sharpleft}
For every $b>1/27$, $\sigma$ is not convex on $(-\infty,b]$.
\end{theorem}

\begin{proof}
Mirror argument: $1/27$ and $b$ lie in $(-\infty,b]$ and also in $[1/27,\infty)$, so a convexity
hypothesis collides with Theorem~\ref{thm:strictconcave} at the midpoint of the pair.
\end{proof}

\begin{corollary}[exact characterisation of the curvature rays]\label{cor:iff}
For every $c\in\R$,
\[
\sigma\ \text{is concave on}\ [c,\infty)\iff c\ge\tfrac1{27},
\qquad
\sigma\ \text{is convex on}\ (-\infty,c]\iff c\le\tfrac1{27}.
\]
\end{corollary}

\begin{proof}
Necessity is Theorems~\ref{thm:sharpright} and \ref{thm:sharpleft}. Sufficiency follows because
concavity and convexity restrict to convex subsets.
\end{proof}

Corollary~\ref{cor:iff} is an adversarial check on the main theorem: it excludes the possibility
that the hypothesis $t\ge1/27$ is slack. The curvature of $\sigma$ changes sign exactly once, at
the image under $h$ of the degenerate critical point $y=1/3$.

\section{The analytic shadow}

\begin{theorem}[differentiability above the critical mass]\label{thm:deriv}
For $t>1/27$, $\sigma$ is differentiable at $t$ with $\sigma'(t)=3\,(27t-1)^{-2/3}$.
\end{theorem}

\begin{proof}
On the open neighbourhood $\{u:27u-1>0\}$ of $t$, $\sigma$ coincides with
$u\mapsto\bigl(1+(27u-1)^{1/3}\bigr)/3$. The chain rule for real powers with nonvanishing argument
gives derivative $\tfrac13\cdot 27\cdot(27t-1)^{1/3-1}$; dividing by $3$ and using
$\tfrac13-1=-\tfrac23$ gives $3(27t-1)^{-2/3}$.
\end{proof}

\begin{theorem}[antitone derivative]\label{thm:antitone}
$t\mapsto3(27t-1)^{-2/3}$ is nonincreasing on $(1/27,\infty)$.
\end{theorem}

\begin{proof}
For $1/27<x\le y$ we have $0<27x-1\le27y-1$ and $w\mapsto w^{-2/3}$ is nonincreasing on
$(0,\infty)$.
\end{proof}

Thus $\sigma'(t)\to\infty$ as $t\downarrow1/27$ (a vertical tangent, reciprocal to $h'(1/3)=0$)
and $\sigma'(t)\to0$ as $t\to\infty$. Since $\sigma$ is not differentiable at the endpoint, the
substitution proof of the previous sections --- valid on the closed ray --- is the correct
argument.

\section{Cube-root growth}

\begin{lemma}\label{lem:scale}
$\cbrt{27t}=3\cbrt{t}$ for all real $t$.
\end{lemma}

\begin{theorem}[upper bound, valid on all of $\R$]\label{thm:upper}
For every $t\in\R$, $\sigma(t)\le\cbrt{t}+\tfrac13$.
\end{theorem}

\begin{proof}
Monotonicity gives $\cbrt{27t-1}\le\cbrt{27t}=3\cbrt{t}$ by Lemma~\ref{lem:scale}; divide by $3$
and add $\tfrac13$.
\end{proof}

\begin{theorem}[lower bound on the physical range]\label{thm:lower}
For $t\ge1/27$, $\cbrt{t}\le\sigma(t)$.
\end{theorem}

\begin{proof}
Let $A=\cbrt{27t-1}\ge0$, so $A^{3}=27t-1$ and $(A+1)^{3}=27t+3A^{2}+3A\ge27t=(3\cbrt{t})^{3}$.
Cubing is strictly increasing, so $3\cbrt{t}\le A+1$, i.e. $\cbrt{t}\le\sigma(t)$.
\end{proof}

\begin{corollary}[cube-root sandwich]\label{cor:sandwich}
For $t\ge1/27$, $\cbrt{t}\le\sigma(t)\le\cbrt{t}+\tfrac13$.
\end{corollary}

Both constants are optimal: the correction vanishes exactly at $t=1/27$, where
$\sigma(1/27)=1/3=\cbrt{1/27}$, and
$\sigma(t)-\cbrt{t}\to\tfrac13$ as $t\to\infty$ because $\cbrt{27t-1}-\cbrt{27t}\to0$.

\section{Merging masses and the order structure}

\begin{theorem}[merging law]\label{thm:merge}
For $s,t\ge1/27$,
\[
\sigma\!\left(s+t-\tfrac1{27}\right)+\tfrac13\;\le\;\sigma(s)+\sigma(t).
\]
\end{theorem}

\begin{proof}
Write $M=s+t-\tfrac1{27}\ge\tfrac1{27}$, $C=\tfrac1{27}$, $D=s+t-\tfrac2{27}\ge0$. If $D=0$ then
$s=t=1/27$ and both sides equal $2/3$. If $D>0$, set $\alpha=(s-\tfrac1{27})/D$ and
$\beta=(t-\tfrac1{27})/D$, so $\alpha,\beta\ge0$ and $\alpha+\beta=1$, and a direct computation
gives $\alpha M+\beta C=s$ and $\beta M+\alpha C=t$. Applying Theorem~\ref{thm:concave} to each,
\[
\alpha\sigma(M)+\beta\tfrac13\le\sigma(s),\qquad \beta\sigma(M)+\alpha\tfrac13\le\sigma(t);
\]
adding and using $\alpha+\beta=1$ collapses the left side to $\sigma(M)+\tfrac13$.
\end{proof}

\begin{lemma}[mass floor]\label{lem:floor}
If $m_{i}\ge1/27$ for all $i$ in a finite set $T$, then $\sum_{i\in T}m_{i}\ge|T|/27$.
\end{lemma}

\begin{theorem}[$n$-fold merging law]\label{thm:mergen}
Let $T$ be finite and nonempty with $n=|T|$ and $m_{i}\ge1/27$ for $i\in T$. Then
\[
\sigma\!\left(\sum_{i\in T}m_{i}-\frac{n-1}{27}\right)+\frac{n-1}{3}
 \;\le\;\sum_{i\in T}\sigma(m_{i}).
\]
\end{theorem}

\begin{proof}
Induction on $n$. For $n=1$ both sides agree. For the step, adjoin an index $a$ to a nonempty $S$
with $|S|=k$. By Lemma~\ref{lem:floor} the residual $R=\sum_{i\in S}m_{i}-\tfrac{k-1}{27}$
satisfies $R\ge1/27$, so Theorem~\ref{thm:merge} applies to $(m_{a},R)$; its left-hand argument is
$\sum_{i\in S\cup\{a\}}m_{i}-\tfrac{k}{27}$, and adding the induction hypothesis
$\sigma(R)+\tfrac{k-1}{3}\le\sum_{i\in S}\sigma(m_{i})$ gives the claim.
\end{proof}

\begin{theorem}[order isomorphism]\label{thm:orderiso}
$\sigma$ is an order isomorphism of $\R$ onto itself with inverse $h$; in particular $\sigma$ is
continuous and surjective, so every growth rate is realised by exactly one mass.
\end{theorem}

\begin{proof}
Proposition~\ref{prop:inv} makes $\sigma$ and $h$ mutually inverse and $\sigma$ strictly
increasing, so $\sigma(x)\le\sigma(y)\iff x\le y$. An order isomorphism of a linear order with the
order topology is a homeomorphism.
\end{proof}

\section{Why $1/27$? The AM--GM bridge}

\begin{theorem}[three-variable AM--GM]\label{thm:amgm}
If $p,q,r\ge0$ and $p+q+r=1$, then $pqr\le\tfrac1{27}$.
\end{theorem}

\begin{proof}
$\cbrt{pqr}\le(p+q+r)/3=1/3$. Equivalently, the inequality follows from nonnegativity of
$(p-q)^{2}$, $(q-r)^{2}$, $(p-r)^{2}$ together with nonnegativity of the pairwise products.
\end{proof}

\begin{theorem}[equality case]\label{thm:amgmeq}
Under the hypotheses of Theorem~\ref{thm:amgm}, $pqr=\tfrac1{27}$ iff $p=q=r=\tfrac13$.
\end{theorem}

\begin{proof}
Sufficiency is a computation. For necessity, equality in AM--GM forces the three numbers to be
equal, hence each equals $1/3$; quantitatively, equality forces
$(3p-1)^{2}=(3q-1)^{2}=(3r-1)^{2}=0$ after combining the squared-difference certificates with the
constraint.
\end{proof}

\begin{corollary}[mass bridge]\label{cor:bridge}
For a three-point probability distribution $(p,q,r)$ one has $\sigma(pqr)\le\sigma(1/27)=1/3$,
with equality iff $p=q=r=1/3$; every non-uniform distribution satisfies $\sigma(pqr)<1/3$.
\end{corollary}

\begin{proof}
Monotonicity of $\sigma$ applied to Theorem~\ref{thm:amgm}, with injectivity of $\sigma$ and
Theorem~\ref{thm:amgmeq} for the equality case.
\end{proof}

Thus $1/27=(1/3)^{3}$ is simultaneously the value $h(1/3)$ at the degenerate critical point, the
exact threshold separating the convex and concave regimes (Corollary~\ref{cor:iff}), and the
maximal product mass of a three-point probability distribution attained only at the uniform
distribution. The guard $t\ge1/27$ in the main theorem therefore says that the mechanism is fed at
least as much mass as the most balanced three-slot distribution can supply, and by
Corollary~\ref{cor:bridge} the boundary is attained by exactly one distribution.

\section{Algorithms}

All primitives below run in $O(1)$ time per evaluation, up to one cube-root extraction.

\subsection*{Sign-aware evaluation}
Evaluating $\sigma$ as \texttt{(1+(27t-1)**(1/3))/3} fails for $t<1/27$, where a floating-point
power of a negative base is not real. The correct primitive is the odd extension
$\mathrm{CBRT}(x)=\operatorname{sign}(x)\,|x|^{1/3}$, after which
$\sigma(t)=\bigl(1+\mathrm{CBRT}(27t-1)\bigr)/3$ is the unique real root of $h(y)=t$ by
Proposition~\ref{prop:inv}.

\subsection*{Curvature-regime classifier}
Given a finite set of masses, decide the applicable regime and certify it with the midpoint gap
\[
G(s,t)=\sigma\!\left(\tfrac{s+t}{2}\right)-\tfrac{\sigma(s)+\sigma(t)}{2}.
\]
Theorem~\ref{thm:strictconcave} gives $G>0$ for distinct $s,t\ge1/27$; Theorem~\ref{thm:convex}
gives $G<0$ for distinct $s,t\le1/27$; for a straddling pair the sign is genuinely indeterminate,
which is the computational face of Corollary~\ref{cor:iff}.

\subsection*{Merge accountant}
Theorem~\ref{thm:mergen} bounds the separate cost $\sum_{i}\sigma(m_{i})$ of $n$ systems below by
$\sigma\bigl(\sum_{i}m_{i}-\tfrac{n-1}{27}\bigr)+\tfrac{n-1}{3}$. Evaluating both sides and
reporting the slack costs $O(n)$ cube roots.

\section{Discussion}

Nearly every statement above is downstream of the identity $h'(y)=3(y-\tfrac13)^{2}$, which forces
$h$ to be an affine copy of $u\mapsto u^{3}$ and $\sigma$ an affine copy of $x\mapsto x^{1/3}$.
The curvature question then reduces to the curvature of the radical, and the location of the
inflection reduces to the location of the critical point; the number $1/27$ is not tuned but is
$h$ evaluated where $h'$ vanishes.

On $(1/27,\infty)$ one may compute $\sigma''(t)=-54(27t-1)^{-5/3}<0$, matching
Theorems~\ref{thm:deriv}--\ref{thm:antitone}. But the interesting statement is concavity on the
\emph{closed} ray, and at the endpoint $\sigma$ is not differentiable; the substitution proof
handles the endpoint uniformly, and the same substitution with a sign flip delivers the convex
mirror, which is what makes the threshold provably sharp.

Sections~5 and 6 are the payoff of concavity: the sandwich locates $\sigma$ within an additive
$1/3$ of a pure radical uniformly on the physical range, and the merging laws convert curvature
into an accounting statement about combining systems.

\section{Future directions}

\begin{conjecture}[degenerate-critical-point rigidity in arbitrary degree]
For $n\ge2$ let $h_{n}$ be the monic degree-$n$ polynomial with $h_{n}'(y)=n(y-1/n)^{n-1}$ and
$h_{n}(0)=0$, and let $\sigma_{n}=h_{n}^{-1}$. Then $\sigma_{n}$ is concave on $[c,\infty)$ iff
$c\ge h_{n}(1/n)$, convex on $(-\infty,h_{n}(1/n)]$ when $n$ is odd, and the gap
$\sigma_{n}(t)-t^{1/n}$ increases from $0$ to $1/n$.
\end{conjecture}
A perfect-power derivative forces the inverse to be a pure radical after an affine change of
variables, collapsing all curvature information to the number $h_{n}(1/n)$; the case $n=3$ is the
present paper. The natural falsifier is even $n$, where $h_{n}$ is not injective on $\R$ and the
convex mirror must fail; if the concave half also fails for some even $n$, the conjecture must be
guarded to odd degrees.

\begin{conjecture}[the curvature threshold as a coefficient locus]
For a real cubic $p(y)=y^{3}+ay^{2}+by+c$ with an increasing inverse branch, the branch is concave
exactly on $[\,p(y^{*}),\infty)$ where $y^{*}=-a/3$ is the inflection of $p$, and
$p(y^{*})=c-ab/3+2a^{3}/27$ is the constant term of the depressed cubic. Hence the curvature
threshold is a polynomial function of the coefficients, vanishing on the locus
$4(b-a^{2}/3)^{3}+27\,p(y^{*})^{2}=0$ where $p$ acquires a triple root.
\end{conjecture}
Concavity of an inverse is governed entirely by the sign of the second derivative of the original
map, so the threshold is the image of the inflection: an analytic question becomes an algebraic
one about coefficient loci. Mechanically one replaces~\eqref{eq:shift} with the general
Tschirnhaus shift.

\begin{conjecture}[simplex transport of the mass bridge]
Let $\Delta_{k}$ be the $k$-simplex and $\Pi(p)=\prod_{i}p_{i}$. Then $\sigma_{k}(\Pi(p))\le1/k$
for all $p\in\Delta_{k}$, with equality iff $p$ is uniform, and $p\mapsto\sigma_{k}(\Pi(p))$ is
strictly Schur-concave with level sets the majorisation classes on $\Delta_{k}$.
\end{conjecture}
Here $1/27=(1/3)^{3}$ is not a constant but the AM--GM extremum of the product functional on the
simplex, so the critical mass should deform with $k$ exactly as the extremum does.

Further questions: is there a quantitative modulus $\kappa(t)>0$ with
$\sigma(\tfrac{s+t}{2})-\tfrac{\sigma(s)+\sigma(t)}{2}\ge\kappa(s-t)^{2}$ locally uniformly on
compacta of $(1/27,\infty)$, with $\kappa(t)\asymp(27t-1)^{-5/3}$ as the exact second derivative
suggests? Is the constant $\tfrac13$ in Theorem~\ref{thm:merge} extremal? Does the order
isomorphism $\sigma$ conjugate natural dynamics on the mass line to tractable dynamics on the
exponent line?

\section{Conclusion}

The Lagrange exponent $\sigma(t)=\bigl(1+\cbrt{27t-1}\bigr)/3$, the global inverse of the
degenerate cubic $h(y)=y^{3}-y^{2}+y/3$, is strictly concave exactly on $[1/27,\infty)$ and
strictly convex exactly on $(-\infty,1/27]$, with a single inflection at the critical mass
$1/27=h(1/3)$ sitting over the coalesced critical point. Above that mass, averaging distributions
never decreases the growth rate, strictly whenever the masses differ, and the same holds for
arbitrary weighted averages. The threshold is sharp in both directions. Concavity then delivers a
cube-root sandwich with optimal constants and a family of merging laws in which the critical
overhead is paid exactly once. Finally, $1/27$ is canonical rather than chosen: it is the AM--GM
extremal product mass of a three-point probability distribution, attained only by the uniform one.

\end{document}

