function CBRT(x):
    if x >= 0: return x^(1/3)
    else:      return -(-x)^(1/3)

function LAGRANGE_EXPONENT(t):
    return (1 + CBRT(27*t - 1)) / 3

function INVERT_CERTIFIED(t):
    y     <- LAGRANGE_EXPONENT(t)
    deriv <- 3*(y - 1/3)^2                 # h'(y), vanishes only at y = 1/3
    if deriv > 1e-12:                       # away from the degenerate point
        y <- y - (h(y) - t) / deriv         # one Newton polish step
    return (y, |h(y) - t|)                  # value and residual certificate

function REGIME_OF(t):
    if t > 1/27: return 'concave (super-critical)'
    if t < 1/27: return 'convex (sub-critical)'
    return 'inflection (critical mass 1/27)'

algorithms.code:
"""Algorithm 1: sign-aware evaluation and certified inversion of the critical cubic.

Given a mass t, return the unique real y with y^3 - y^2 + y/3 = t, together with a
residual certificate |h(y) - t|.  The naive expression (1 + (27*t - 1)**(1/3))/3 is
wrong for t < 1/27, where a floating-point fractional power of a negative base is not
a real number; the correct primitive is the odd extension of the cube root.
"""

from __future__ import annotations

from typing import Tuple

CRITICAL_MASS: float = 1.0 / 27.0


def cbrt(x: float) -> float:
    """Sign-aware real cube root: the unique real u with u ** 3 == x."""
    if x >= 0.0:
        return x ** (1.0 / 3.0)
    return -((-x) ** (1.0 / 3.0))


def lagrange_cubic(y: float) -> float:
    """The critical cubic h(y) = y^3 - y^2 + y/3 = ((3y - 1)^3 + 1) / 27."""
    return y ** 3 - y ** 2 + y / 3.0


def lagrange_exponent(t: float) -> float:
    """The Lagrange exponent sigma(t) = (1 + cbrt(27 t - 1)) / 3."""
    return (1.0 + cbrt(27.0 * t - 1.0)) / 3.0


def invert_certified(t: float) -> Tuple[float, float]:
    """Return (sigma(t), residual) where residual = |h(sigma(t)) - t|.

    The residual is zero in exact arithmetic; numerically it measures the accuracy of
    the single cube-root extraction.  One optional Newton polish step is applied when
    the derivative h'(y) = 3 (y - 1/3)^2 is not degenerate, which recovers full double
    precision away from the critical point y = 1/3.
    """
    y = lagrange_exponent(t)
    deriv = 3.0 * (y - 1.0 / 3.0) ** 2
    if deriv > 1e-12:
        y -= (lagrange_cubic(y) - t) / deriv
    return y, abs(lagrange_cubic(y) - t)


def regime_of(t: float) -> str:
    """Name the curvature regime containing the mass t."""
    if t > CRITICAL_MASS:
        return "concave (super-critical)"
    if t < CRITICAL_MASS:
        return "convex (sub-critical)"
    return "inflection (critical mass 1/27)"


if __name__ == "__main__":
    for t in (-2.0, 0.0, CRITICAL_MASS, 1.0 / 3.0, 28.0 / 27.0, 1e6):
        y, res = invert_certified(t)
        print(f"t = {t:>12.6g}   sigma(t) = {y:>14.9f}   residual = {res:.2e}   {regime_of(t)}")
